create table if not exists public.stacks(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,name text not null,description text,status text not null default 'active' check(status in ('active','archived')),created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(workspace_id,name));
alter table public.stacks enable row level security;
create policy stacks_workspace_select on public.stacks for select to authenticated using(public.is_workspace_member(workspace_id));
create policy stacks_workspace_insert on public.stacks for insert to authenticated with check(public.is_workspace_member(workspace_id) and created_by=auth.uid());
create policy stacks_workspace_update on public.stacks for update to authenticated using(public.is_workspace_member(workspace_id)) with check(public.is_workspace_member(workspace_id));
create policy stacks_workspace_delete on public.stacks for delete to authenticated using(public.is_workspace_member(workspace_id));
grant select,insert,update,delete on public.stacks to authenticated;
create index if not exists stacks_workspace_created_idx on public.stacks(workspace_id,created_at desc);
alter table public.projects add column if not exists stack_id uuid references public.stacks(id) on delete set null;
create index if not exists projects_stack_idx on public.projects(stack_id);
alter table public.environments add column if not exists stack_id uuid references public.stacks(id) on delete set null;
create index if not exists environments_stack_idx on public.environments(stack_id);
create or replace function public.enforce_project_stack_workspace() returns trigger language plpgsql set search_path=public as $$ declare sw uuid; begin if new.stack_id is null then return new; end if; select s.workspace_id into sw from public.stacks s where s.id=new.stack_id; if sw is null or sw is distinct from new.workspace_id then raise exception 'project stack must belong to the same workspace'; end if; return new; end $$;
drop trigger if exists projects_stack_workspace_guard on public.projects;create trigger projects_stack_workspace_guard before insert or update of stack_id,workspace_id on public.projects for each row execute function public.enforce_project_stack_workspace();revoke all on function public.enforce_project_stack_workspace() from public,anon,authenticated;
create or replace function public.enforce_environment_stack_workspace() returns trigger language plpgsql set search_path=public as $$ declare sw uuid; begin if new.stack_id is null then return new; end if; select s.workspace_id into sw from public.stacks s where s.id=new.stack_id; if sw is null or sw is distinct from new.workspace_id then raise exception 'environment stack must belong to the same workspace'; end if; return new; end $$;
drop trigger if exists environments_stack_workspace_guard on public.environments;create trigger environments_stack_workspace_guard before insert or update of stack_id,workspace_id on public.environments for each row execute function public.enforce_environment_stack_workspace();revoke all on function public.enforce_environment_stack_workspace() from public,anon,authenticated;
revoke select,insert,update,references on public.projects from authenticated;
grant select(id,client_id,workspace_id,stack_id,name,description,status,git_url,git_branch,repo_folder,language,created_at,updated_at,created_by) on public.projects to authenticated;
grant insert(client_id,workspace_id,stack_id,name,description,status,git_url,git_branch,repo_folder,language,created_by) on public.projects to authenticated;
grant update(client_id,workspace_id,stack_id,name,description,status,git_url,git_branch,repo_folder,language) on public.projects to authenticated;